mapper.select:
select

from BOK_BOOKSET_EXT
where BOOKSET_ID = #{booksetId,jdbcType=VARCHAR}
and PARAM_CODE = #{paramCode,jdbcType=VARCHAR}

mapper.delete:
delete from BOK_BOOKSET_EXT
where BOOKSET_ID = #{booksetId,jdbcType=VARCHAR}
  and PARAM_CODE = #{paramCode,jdbcType=VARCHAR}

mapper.update:
update BOK_BOOKSET_EXT
set PARAM_VALUE = #{paramValue,jdbcType=VARCHAR},
    PARAM_NAME = #{paramName,jdbcType=VARCHAR},
    REMARK = #{remark,jdbcType=VARCHAR},
    UPDATE_USER = #{updateUser,jdbcType=VARCHAR},
    UPDATE_TIME = #{updateTime,jdbcType=TIMESTAMP}
where BOOKSET_ID = #{booksetId,jdbcType=VARCHAR}
  and PARAM_CODE = #{paramCode,jdbcType=VARCHAR}
